PW_PL = PW + "\u0565\u0580\u0568"


def walk(obj):
    if isinstance(obj, str):
        return obj.replace("PASSWORDS", PW_PL).replace("PASSWORD", PW)
    if isinstance(obj, list):
        return [walk(x) for x in obj]
    if isinstance(obj, dict):
        return {k: walk(v) for k, v in obj.items()}
    return obj


def main() -> None:
    data = walk(json.loads(RAW))
    OUT.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

    checks = [
        (data["introTitle"].startswith("\u0541\u0565\u0580"), "introTitle starts with Dzer"),
        (PW in data["tips"][0]["items"][0], "password in tip"),
        ("\u0578\u0582\u056a\u0565\u0572" in data["tips"][0]["items"][0], "ushegh not ushegh"),
        ("\u0563\u0575\u0578\u0582\u0572\u0561\u057f" in data["introBody"], "gyughatntes"),
    ]
    failed = [msg for ok, msg in checks if not ok]
    if failed:
        raise SystemExit("Validation failed: " + ", ".join(failed))

    Path(__file__).resolve().parent.joinpath("_gen_ok.txt").write_text("ok\n", encoding="utf-8")


if __name__ == "__main__":
    main()
